     8  /**
     9   * xmlXIncludeIncludeNode:
    10   * @ctxt: an XInclude context
    11   * @nr: the node number
    12   *
    13   * Implement the infoset replacement for the given node
    14   *
    15   * Returns 0 if substitution succeeded, -1 if some processing failed
    16   */
    17  static int
    18  xmlXIncludeIncludeNode(xmlXIncludeCtxtPtr ctxt, int nr) {
    19      xmlNodePtr cur, end, list, tmp;
    20
    21      if (ctxt == NULL)
    22          return(-1);
    23      if ((nr < 0) || (nr >= ctxt->incNr))
    24          return(-1);
    25      cur = ctxt->incTab[nr]->ref;
    26      if ((cur == NULL) || (cur->type == XML_NAMESPACE_DECL))
    27          return(-1);
    28
    29      list = ctxt->incTab[nr]->inc;
    30      ctxt->incTab[nr]->inc = NULL;
    31
    32      /*
    33       * Check against the risk of generating a multi-rooted document
    34       */
    35      if ((cur->parent != NULL) &&
    36          (cur->parent->type != XML_ELEMENT_NODE)) {
    37          int nb_elem = 0;
    38
    39          tmp = list;
    40          while (tmp != NULL) {
    41              if (tmp->type == XML_ELEMENT_NODE)
    42                  nb_elem++;
    43              tmp = tmp->next;
    44          }
    45          if (nb_elem > 1) {
    46              xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
    47                             XML_XINCLUDE_MULTIPLE_ROOT,
    48                         "XInclude error: would result in multiple root nodes\n",
    49                             NULL);
    50              xmlFreeNodeList(list);
    51              return(-1);
    52          }
    53      }
    54
    55      if (ctxt->parseFlags & XML_PARSE_NOXINCNODE) {
    56          /*
    57           * Add the list of nodes
    58           */
    59          while (list != NULL) {
    60              end = list;
    61              list = list->next;
    62
    63              xmlAddPrevSibling(cur, end);
    64          }
    65          xmlUnlinkNode(cur);
    66          xmlFreeNode(cur);
    67      } else {
    68          xmlNodePtr child, next;
    69
    70          /*
    71           * Change the current node as an XInclude start one, and add an
    72           * XInclude end one
    73           */
    74          if (ctxt->incTab[nr]->fallback)
    75              xmlUnsetProp(cur, BAD_CAST "href");
    76          cur->type = XML_XINCLUDE_START;
    77          /* Remove fallback children */
    78          for (child = cur->children; child != NULL; child = next) {
    79              next = child->next;
    80              xmlUnlinkNode(child);
    81              xmlFreeNode(child);
    82          }
    83          end = xmlNewDocNode(cur->doc, cur->ns, cur->name, NULL);
    84          if (end == NULL) {
    85              xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
    86                             XML_XINCLUDE_BUILD_FAILED,
    87                             "failed to build node\n", NULL);
    88              xmlFreeNodeList(list);
    89              return(-1);
    90          }
    91          end->type = XML_XINCLUDE_END;
    92          xmlAddNextSibling(cur, end);
    93
    94          /*
    95           * Add the list of nodes
    96           */
    97          while (list != NULL) {
    98              cur = list;
    99              list = list->next;
   100
   101              xmlAddPrevSibling(end, cur);
   102          }
   103      }
   104
   105
   106      return(0);
   107  }
