   109  /**
   110   * xmlXIncludeTestNode:
   111   * @ctxt: the XInclude processing context
   112   * @node: an XInclude node
   113   *
   114   * test if the node is an XInclude node
   115   *
   116   * Returns 1 true, 0 otherwise
   117   */
   118  static int
   119  xmlXIncludeTestNode(xmlXIncludeCtxtPtr ctxt, xmlNodePtr node) {
   120      if (node == NULL)
   121          return(0);
   122      if (node->type != XML_ELEMENT_NODE)
   123          return(0);
   124      if (node->ns == NULL)
   125          return(0);
   126      if ((xmlStrEqual(node->ns->href, XINCLUDE_NS)) ||
   127          (xmlStrEqual(node->ns->href, XINCLUDE_OLD_NS))) {
   128          if (xmlStrEqual(node->ns->href, XINCLUDE_OLD_NS)) {
   129              if (ctxt->legacy == 0) {
   130  #if 0 /* wait for the XML Core Working Group to get something stable ! */
   131                  xmlXIncludeWarn(ctxt, node, XML_XINCLUDE_DEPRECATED_NS,
   132                         "Deprecated XInclude namespace found, use %s",
   133                                  XINCLUDE_NS);
   134  #endif
   135                  ctxt->legacy = 1;
   136              }
   137          }
   138          if (xmlStrEqual(node->name, XINCLUDE_NODE)) {
   139              xmlNodePtr child = node->children;
   140              int nb_fallback = 0;
   141
   142              while (child != NULL) {
   143                  if ((child->type == XML_ELEMENT_NODE) &&
   144                      (child->ns != NULL) &&
   145                      ((xmlStrEqual(child->ns->href, XINCLUDE_NS)) ||
   146                       (xmlStrEqual(child->ns->href, XINCLUDE_OLD_NS)))) {
   147                      if (xmlStrEqual(child->name, XINCLUDE_NODE)) {
   148                          xmlXIncludeErr(ctxt, node,
   149                                         XML_XINCLUDE_INCLUDE_IN_INCLUDE,
   150                                         "%s has an 'include' child\n",
   151                                         XINCLUDE_NODE);
   152                          return(0);
   153                      }
   154                      if (xmlStrEqual(child->name, XINCLUDE_FALLBACK)) {
   155                          nb_fallback++;
   156                      }
   157                  }
   158                  child = child->next;
   159              }
   160              if (nb_fallback > 1) {
   161                  xmlXIncludeErr(ctxt, node, XML_XINCLUDE_FALLBACKS_IN_INCLUDE,
   162                                 "%s has multiple fallback children\n",
   163                                 XINCLUDE_NODE);
   164                  return(0);
   165              }
   166              return(1);
   167          }
   168          if (xmlStrEqual(node->name, XINCLUDE_FALLBACK)) {
   169              if ((node->parent == NULL) ||
   170                  (node->parent->type != XML_ELEMENT_NODE) ||
   171                  (node->parent->ns == NULL) ||
   172                  ((!xmlStrEqual(node->parent->ns->href, XINCLUDE_NS)) &&
   173                   (!xmlStrEqual(node->parent->ns->href, XINCLUDE_OLD_NS))) ||
   174                  (!xmlStrEqual(node->parent->name, XINCLUDE_NODE))) {
   175                  xmlXIncludeErr(ctxt, node,
   176                                 XML_XINCLUDE_FALLBACK_NOT_IN_INCLUDE,
   177                                 "%s is not the child of an 'include'\n",
   178                                 XINCLUDE_FALLBACK);
   179              }
   180          }
   181      }
   182      return(0);
   183  }
