   185  /**
   186   * xmlXIncludeDoProcess:
   187   * @ctxt: the XInclude processing context
   188   * @doc: an XML document
   189   * @tree: the top of the tree to process
   190   * @skipRoot: don't process the root node of the tree
   191   *
   192   * Implement the XInclude substitution on the XML document @doc
   193   *
   194   * Returns 0 if no substitution were done, -1 if some processing failed
   195   *    or the number of substitutions done.
   196   */
   197  static int
   198  xmlXIncludeDoProcess(xmlXIncludeCtxtPtr ctxt, xmlDocPtr doc, xmlNodePtr tree,
   199                       int skipRoot) {
   200      xmlNodePtr cur;
   201      int ret = 0;
   202      int i, start;
   203
   204      if ((doc == NULL) || (tree == NULL) || (tree->type == XML_NAMESPACE_DECL))
   205          return(-1);
   206      if ((skipRoot) && (tree->children == NULL))
   207          return(-1);
   208      if (ctxt == NULL)
   209          return(-1);
   210
   211      if (doc->URL != NULL) {
   212          ret = xmlXIncludeURLPush(ctxt, doc->URL);
   213          if (ret < 0)
   214              return(-1);
   215      }
   216      start = ctxt->incNr;
   217
   218      /*
   219       * TODO: The phases must run separately for recursive inclusions.
   220       *
   221       * - Phase 1 should start with top-level XInclude nodes, load documents,
   222       *   execute XPointer expressions, then process only the result nodes
   223       *   (not whole document, see bug #324081) and only for phase 1
   224       *   recursively. We will need a backreference from xmlNodes to
   225       *   xmlIncludeRefs to detect references that were already visited.
   226       *   This can also be used for proper cycle detection, see bug #344240.
   227       *
   228       * - Phase 2 should visit all top-level XInclude nodes and expand
   229       *   possible subreferences in the replacement recursively.
   230       *
   231       * - Phase 3 should finally replace the top-level XInclude nodes.
   232       *   It could also be run together with phase 2.
   233       */
   234
   235      /*
   236       * First phase: lookup the elements in the document
   237       */
   238      if (skipRoot)
   239          cur = tree->children;
   240      else
   241          cur = tree;
   242      do {
   243          /* TODO: need to work on entities -> stack */
   244          if (xmlXIncludeTestNode(ctxt, cur) == 1) {
   245  #ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
   246              /*
   247               * Avoid superlinear expansion by limiting the total number
   248               * of replacements.
   249               */
   250              if (ctxt->incTotal >= 20)
   251                  return(-1);
   252  #endif
   253              ctxt->incTotal++;
   254              xmlXIncludePreProcessNode(ctxt, cur);
   255          } else if ((cur->children != NULL) &&
   256                     (cur->children->type != XML_ENTITY_DECL) &&
   257                     (cur->children->type != XML_XINCLUDE_START) &&
   258                     (cur->children->type != XML_XINCLUDE_END)) {
   259              cur = cur->children;
   260              continue;
   261          }
   262          do {
   263              if (cur == tree)
   264                  break;
   265              if (cur->next != NULL) {
   266                  cur = cur->next;
   267                  break;
   268              }
   269              cur = cur->parent;
   270          } while (cur != NULL);
   271      } while ((cur != NULL) && (cur != tree));
   272
   273      /*
   274       * Second Phase : collect the infosets fragments
   275       */
   276      for (i = start;i < ctxt->incNr; i++) {
   277          xmlXIncludeLoadNode(ctxt, i);
   278          ret++;
   279      }
   280
   281      /*
   282       * Third phase: extend the original document infoset.
   283       *
   284       * Originally we bypassed the inclusion if there were any errors
   285       * encountered on any of the XIncludes.  A bug was raised (bug
   286       * 132588) requesting that we output the XIncludes without error,
   287       * so the check for inc!=NULL || xptr!=NULL was put in.  This may
   288       * give some other problems in the future, but for now it seems to
   289       * work ok.
   290       *
   291       */
   292      for (i = ctxt->incBase;i < ctxt->incNr; i++) {
   293          if (ctxt->incTab[i]->skip == 0)
   294              xmlXIncludeIncludeNode(ctxt, i);
   295      }
   296
   297      if (doc->URL != NULL)
   298          xmlXIncludeURLPop(ctxt);
   299      return(ret);
   300  }
