   302  /**
   303   * xmlXIncludeSetFlags:
   304   * @ctxt:  an XInclude processing context
   305   * @flags: a set of xmlParserOption used for parsing XML includes
   306   *
   307   * Set the flags used for further processing of XML resources.
   308   *
   309   * Returns 0 in case of success and -1 in case of error.
   310   */
   311  int
   312  xmlXIncludeSetFlags(xmlXIncludeCtxtPtr ctxt, int flags) {
   313      if (ctxt == NULL)
   314          return(-1);
   315      ctxt->parseFlags = flags;
   316      return(0);
   317  }
