   319  /**
   320   * xmlXIncludeProcessTreeFlagsData:
   321   * @tree: an XML node
   322   * @flags: a set of xmlParserOption used for parsing XML includes
   323   * @data: application data that will be passed to the parser context
   324   *        in the _private field of the parser context(s)
   325   *
   326   * Implement the XInclude substitution on the XML node @tree
   327   *
   328   * Returns 0 if no substitution were done, -1 if some processing failed
   329   *    or the number of substitutions done.
   330   */
   331
   332  int
   333  xmlXIncludeProcessTreeFlagsData(xmlNodePtr tree, int flags, void *data) {
   334      xmlXIncludeCtxtPtr ctxt;
   335      int ret = 0;
   336
   337      if ((tree == NULL) || (tree->type == XML_NAMESPACE_DECL) ||
   338          (tree->doc == NULL))
   339          return(-1);
   340
   341      ctxt = xmlXIncludeNewContext(tree->doc);
   342      if (ctxt == NULL)
   343          return(-1);
   344      ctxt->_private = data;
   345      ctxt->base = xmlStrdup((xmlChar *)tree->doc->URL);
   346      xmlXIncludeSetFlags(ctxt, flags);
